/**
 * Tell the person who asked for this run that CI is actually running, and where to
 * watch it.
 *
 * A person's `/agent` on a pull request goes through validation, and the wait is
 * minutes long; a person who typed a command and saw nothing happen has no way to
 * tell a queued run from a broken workflow. So this says the one fact that is true
 * while it runs -- and nothing more: what runs after CI is decided by the result
 * (checks that fail send the engineer, not the agent the person named), so the
 * comment does not promise an agent.
 *
 * Person-asked only: an agent's own push already knows its validation is running --
 * `create_pr`'s return text says so -- and a comment per push would be noise on the
 * thread. Reused CI says nothing for the same reason: the person's comment is its
 * own record, and whoever the verdict dispatches starts seconds later.
 */
function notifyCiWaiting(repo: string, number: string, runId: number): void {
  const body = [
    LLM_CONTEXT_TAG.write("exclude"),
    `Atomaton: CI is running on this pull request (${runUrl(repo, runId)}). Its result decides who works next.`,
