/**
 * The notification, as the real script posts it with a fake `gh` answering.
 *
 * `runCiAndWait`'s reuse decision and the comment it posts are the behaviour the
 * issue is about, and neither is reachable from the pure functions: the decision
 * lives in the poll loop. So these run the whole script the way the workflow does,
 * with `--timeout-seconds 1` bounding the wait -- the poll interval is 10s, so one
 * loop iteration is one test's worth.
 */
const HEAD_SHA = "abc123def4567890abcdef1234567890abcdef12";
const RUN_ID = 4242;

function runsJson(runs: unknown[]): string {
  return JSON.stringify({ total_count: runs.length, workflow_runs: runs });
}

function actionRun(status: string, conclusion: string | null): Record<string, unknown> {
  return {
    id: RUN_ID,
    status,
    conclusion,
    head_sha: HEAD_SHA,
    path: ".github/workflows/ci.yml",
    // Far past any test's clock: `pickDispatchedRun` filters on `created_at >= since`,
    // and `since` is the script's own start time.
    created_at: "2099-01-01T00:00:00Z",
    event: "workflow_dispatch",
  };
}

interface ValidateRun {
  status: number | null;
  ghCalls: string[][];
  comments: string[];
  out: Record<string, string>;
}

function runValidation(opts: { askedByPerson: boolean; firstRun: Record<string, unknown> }): ValidateRun {
  // The runs-list answer is read more than once -- the reuse check, then one poll --
  // and `attempt` is what makes the first read and the first poll different answers.
  const runsRule = { match: ["actions/runs?event=workflow_dispatch"] };
  const rules = [
    { ...runsRule, stdout: runsJson(opts.firstRun ? [opts.firstRun] : []), attempt: 1 },
    { ...runsRule, stdout: runsJson([actionRun("in_progress", null)]), attempt: 2 },
    { ...runsRule, stdout: runsJson([actionRun("completed", "success")]), attempt: 3 },
    { match: ["repos/o/r/pulls/7"], stdout: JSON.stringify({ head: { sha: HEAD_SHA }, base: { ref: "main" } }) },
    { match: ["repos/o/r/rules/branches/main"], stdout: "[]" },
    { match: ["repos/o/r/issues/7/comments"], stdout: "[]" },
    { match: ["repos/o/r/issues/7"], stdout: "just a body" },
    { match: ["repos/o/r/commits/"], stdout: "2099-01-01T00:00:00Z" },
    // The dispatch itself: `--ref` is what keeps this rule off the runs-list call,
    // whose URL carries `workflow_dispatch` -- the words the obvious rule would match.
    { match: ["--ref", "ci.yml"], stdout: "" },
  ];
  const dir = mkdtempSync(join(tmpdir(), "atomaton-validate-"));
  try {
    const outputFile = join(dir, "out");
    writeFileSync(outputFile, "");
    const report = join(dir, "report");
    writeFileSync(report, "");
    const defDir = join(dir, "defs");
    mkdirSync(defDir);
    const result = runWithFakeGh(scriptPath("validate_pull_request.ts"), [
      "--repo", "o/r",
      "--number", "7",
      "--branch", "atomaton/issue-7",
      "--workflow", "ci.yml",
      "--def-dir", defDir,
      "--deliverable-report", report,
      "--timeout-seconds", "1",
      "--asked-by-person", opts.askedByPerson ? "true" : "false",
    ], { rules, env: { GITHUB_OUTPUT: outputFile } });
    const comments = result.ghCalls
      .filter((call) => call[0] === "issue" && call[1] === "comment")
      .map((call) => call[call.indexOf("--body") + 1]);
    return { status: result.status, ghCalls: result.ghCalls, comments, out: parseGithubOutput(readFileSync(outputFile, "utf8")) };
  } finally {
    removeTemp(dir);
  }
}
